    11	/** JPQL implementation of {@link CourtDao}. */
    12	@Repository
    13	public class CourtDaoImpl extends AbstractDao<Court> implements CourtDao {
    14	
    15	    public CourtDaoImpl() {
    16	        super(Court.class);
    17	    }
    18	
    19	    @Override
    20	    public Optional<Court> findByCourtNumber(Integer courtNumber) {
    21	        return singleResult(em.createQuery(
    22	                        "SELECT c FROM Court c WHERE c.courtNumber = :courtNumber AND c.deleted = false", Court.class)
    23	                .setParameter("courtNumber", courtNumber));
    24	    }
    25	
    26	    @Override
    27	    public boolean existsByCourtNumber(Integer courtNumber) {
    28	        return exists(em.createQuery(
    29	                        "SELECT COUNT(c) FROM Court c WHERE c.courtNumber = :courtNumber AND c.deleted = false",
    30	                        Long.class)
    31	                .setParameter("courtNumber", courtNumber));
    32	    }
    33	
    34	    /**
    35	     * {@inheritDoc}
    36	     * <p>
    37	     * Uses {@code em.find} with a lock mode (JPQL {@code setLockMode} on a filtered query is not portable),
    38	     * then applies the soft-delete filter in memory. Locking a deleted row is harmless: it is released with
    39	     * the transaction.
    40	     */
    41	    @Override
    42	    public Optional<Court> findByIdForUpdate(Long id) {
    43	        if (id == null) {
    44	            return Optional.empty();
    45	        }
    46	        return Optional.ofNullable(em.find(Court.class, id, LockModeType.PESSIMISTIC_WRITE))
    47	                .filter(court -> !court.isDeleted());
    48	    }
    49	}
