     1	package sk.knizat.tennisclub.dao.impl;
     2	
     3	import jakarta.persistence.TypedQuery;
     4	import org.springframework.stereotype.Repository;
     5	import sk.knizat.tennisclub.dao.AbstractDao;
     6	import sk.knizat.tennisclub.dao.ReservationDao;
     7	import sk.knizat.tennisclub.entity.Reservation;
     8	
     9	import java.time.Instant;
    10	import java.util.List;
    11	
    12	/**
    13	 * JPQL implementation of {@link ReservationDao}. List queries {@code JOIN FETCH} the court, its surface type
    14	 * and the user so that mappers can read the whole graph without N+1 selects.
    15	 */
    16	@Repository
    17	public class ReservationDaoImpl extends AbstractDao<Reservation> implements ReservationDao {
    18	
    19	    private static final String SELECT_GRAPH =
    20	            "SELECT r FROM Reservation r JOIN FETCH r.court c JOIN FETCH c.surfaceType JOIN FETCH r.user u ";
    21	
    22	    public ReservationDaoImpl() {
    23	        super(Reservation.class);
    24	    }
    25	
    26	    /**
    27	     * {@inheritDoc}
    28	     * <p>
    29	     * Only {@code r.deleted} is filtered on purpose: the court is matched by number regardless of its own
    30	     * deleted flag, so reservations made on a since-removed court remain listable.
    31	     */
    32	    @Override
    33	    public List<Reservation> findByCourtNumberOrderByCreatedAt(Integer courtNumber) {
    34	        return em.createQuery(SELECT_GRAPH
    35	                        + "WHERE c.courtNumber = :courtNumber AND r.deleted = false "
    36	                        + "ORDER BY r.createdAt ASC, r.id ASC", Reservation.class)
    37	                .setParameter("courtNumber", courtNumber)
    38	                .getResultList();
    39	    }
    40	
    41	    @Override
    42	    public List<Reservation> findByPhoneNumber(String phoneNumber, boolean futureOnly, Instant now) {
    43	        StringBuilder jpql = new StringBuilder(SELECT_GRAPH)
    44	                .append("WHERE u.phoneNumber = :phoneNumber AND u.deleted = false AND r.deleted = false ");
    45	        if (futureOnly) {
    46	            jpql.append("AND r.startTime > :now ");
    47	        }
    48	        jpql.append("ORDER BY r.startTime ASC, r.id ASC");
    49	        TypedQuery<Reservation> query = em.createQuery(jpql.toString(), Reservation.class)
    50	                .setParameter("phoneNumber", phoneNumber);
    51	        if (futureOnly) {
    52	            query.setParameter("now", now);
    53	        }
    54	        return query.getResultList();
    55	    }
    56	
    57	    @Override
    58	    public List<Reservation> findAllOrderByStartTime() {
    59	        return em.createQuery(SELECT_GRAPH
    60	                        + "WHERE r.deleted = false ORDER BY r.startTime ASC, r.id ASC", Reservation.class)
    61	                .getResultList();
    62	    }
    63	
    64	    @Override
    65	    public boolean existsOverlapping(Long courtId, Instant start, Instant end, Long excludeReservationId) {
    66	        StringBuilder jpql = new StringBuilder(
    67	                "SELECT COUNT(r) FROM Reservation r WHERE r.court.id = :courtId AND r.deleted = false "
    68	                        + "AND r.startTime < :end AND r.endTime > :start ");
    69	        if (excludeReservationId != null) {
    70	            jpql.append("AND r.id <> :excludeId");
    71	        }
    72	        TypedQuery<Long> query = em.createQuery(jpql.toString(), Long.class)
    73	                .setParameter("courtId", courtId)
    74	                .setParameter("start", start)
    75	                .setParameter("end", end);
    76	        if (excludeReservationId != null) {
    77	            query.setParameter("excludeId", excludeReservationId);
    78	        }
    79	        return exists(query);
    80	    }
    81	
    82	    @Override
    83	    public boolean existsFutureByCourt(Long courtId, Instant now) {
    84	        return exists(em.createQuery(
    85	                        "SELECT COUNT(r) FROM Reservation r WHERE r.court.id = :courtId AND r.deleted = false "
    86	                                + "AND r.startTime > :now", Long.class)
    87	                .setParameter("courtId", courtId)
    88	                .setParameter("now", now));
    89	    }
    90	
    91	    @Override
    92	    public boolean existsFutureByUser(Long userId, Instant now) {
    93	        return exists(em.createQuery(
    94	                        "SELECT COUNT(r) FROM Reservation r WHERE r.user.id = :userId AND r.deleted = false "
    95	                                + "AND r.startTime > :now", Long.class)
    96	                .setParameter("userId", userId)
    97	                .setParameter("now", now));
    98	    }
    99	}
