    13	/** Integration tests of {@link CourtDao}. */
    14	class CourtDaoTest extends AbstractDaoTest {
    15	
    16	    @Autowired
    17	    private CourtDao courtDao;
    18	
    19	    @Test
    20	    void should_findByCourtNumber_when_nonDeletedExists() {
