    46	    private Instant updatedAt;
    47	
    48	    @Setter(AccessLevel.NONE)
    49	    @Column(name = "deleted", nullable = false)
    50	    private boolean deleted = false;
    51	
    52	    @Setter(AccessLevel.NONE)
